import unittest
class TestTypecasting(unittest.TestCase):
    def test_run(self):
        out = run_student_code(inputs=['1.34'])
        self.assertIn('Integer part: 1', out, 'Integer part incorrect | Parte entera incorrecta | Zati osoa okerra')
